[
  {
    "qid": "0003-t2i-1",
    "sample_id": "0003_摩根_4daff88d.webp",
    "task": "t2i",
    "knowledge_dim": "brand_commercial",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "深绿色双座敞篷复古跑车",
        "中央直瀑式镀铬圆拱进气格栅",
        "车头独立凸出的双圆形大灯",
        "向后平滑下垂过渡的隆起前轮拱与翼子板",
        "金属钢丝辐条轮毂"
      ],
      "anchor_features": [
        "摩根汽车标志性直瀑马蹄形水箱格栅",
        "二十世纪三四十年代延续至今的经典流线下垂水滴翼子板",
        "复古密集钢丝辐条轮圈与长车头短座舱手工跑车身形"
      ],
      "trigger_check": "模型读到提示词中的“深绿色摩根（Morgan）双座敞篷跑车”，需准确调用对英国百年手工跑车摩根品牌的经典复古形制知识，才能正确画出其直瀑格栅、特有翼子板和钢丝轮毂，而非现代通用跑车。",
      "counterexample_test": "若模型仅画成现代平滑跑车（如现代捷豹、保时捷）或普通老爷车而缺失直瀑圆拱水箱护罩及下垂翼子板，则无法通过校验。"
    },
    "gen_prompt": "一张汽车文化杂志封面级别的实拍照片：一辆经典的深绿色摩根（Morgan）双座敞篷跑车停在秋季英格兰乡村庄园外的碎石路旁，午后暖阳斜照在修长的发动机舱上，背景为典雅的红砖古堡建筑与金黄色落叶，画面构图工整，充满英伦复古韵味。",
    "implicit_checks": [
      {
        "check": "车头呈现摩根标志性的垂直排列直瀑式镀铬圆拱进气格栅，两侧配双圆形大灯",
        "knowledge": "[solid] 摩根（Morgan）全系传统经典跑车采用标志性的拱形直瀑镀铬中网与外露双圆头灯布局",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "格栅为现代横向/蜂窝状进气口，或车头为扁平现代跑车前脸，无圆拱直瀑特征",
          "1": "具有复古车头格栅，但非直瀑式垂直条纹或大灯非经典圆形分立布局",
          "2": "准确呈现中央立式圆拱形直瀑金属格栅，两侧对称分布凸出的圆形大灯"
        },
        "acceptable_variants": [
          "格栅带有轻微弧度倾斜",
          "车头配有复古辅助小射灯或镀铬保险杠"
        ]
      },
      {
        "check": "前轮翼子板呈圆润水滴弧形且自大灯下方顺滑向后下垂延展至车身侧面",
        "knowledge": "[solid] 摩根跑车车身延续1930年代以来的经典翼子板造型，前轮拱呈优雅水滴下垂曲线连接踏板",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "翼子板为现代平直一体化包覆车身，无独立隆起与下垂弧度",
          "1": "轮拱有外凸但线条生硬，未形成从车头顺滑下垂至车身侧腰的流动弧线",
          "2": "完美呈现自车灯向后优雅下延的立体弧面翼子板，具有鲜明战前古典跑车流线特征"
        },
        "acceptable_variants": [
          "翼子板与侧踏板一体相连",
          "翼子板上带有复古后视镜或转向灯"
        ]
      },
      {
        "check": "车轮采用经典的金属密集钢丝辐条轮毂造型",
        "knowledge": "[solid] 摩根传统跑车标配或标志性选装多辐金属钢丝轮圈（Wire Wheels）",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "车轮为现代五辐/双五辐铝合金轮毂或全封闭轮罩",
          "1": "轮毂为普通多辐条但缺乏纤细密集的钢丝交叉质感",
          "2": "清晰呈现金属光泽的密集交叉钢丝辐条复古轮毂结构"
        },
        "acceptable_variants": [
          "配有中央锁止旋钮（Knock-off spinner）",
          "带有复古白边轮胎"
        ]
      }
    ],
    "facet_tags": [
      "objects",
      "tech_machinery",
      "real_world_scene",
      "material_texture",
      "lighting_atmosphere"
    ],
    "gate_spec": {
      "required_subjects": [
        "摩根跑车"
      ],
      "theme_definition": "英格兰秋季庄园环境中的深绿色经典摩根敞篷跑车实拍"
    },
    "expected_failure_modes": [
      "画成现代流线型跑车（如现代阿斯顿马丁或捷豹），缺失直瀑式格栅",
      "轮毂画成现代五辐铝合金轮圈而非密集钢丝辐条轮",
      "车身前翼子板平直化，缺失摩根标志性的古典下垂曲线"
    ],
    "notes": "考察模型对英国经典小众手工跑车品牌摩根（Morgan）标志性家族外观（直瀑中网、古典下垂翼子板、钢丝圈）的世界知识召回能力。"
  }
]
